mapper.select:
select a.id, a.advance_delivery_id, a.advance_delivery_detail_id, a.material_id, a.predict_count, a.actual_count, a.status, a.batch_code, a.next_flag, a.remark, a.create_by, a.create_time, a.update_by, a.update_time, a.dept_id, a.dept_name, b.code as advanceDeliveryCode, b.`type` as advanceDeliveryType, b.create_by as maker, m.code as materialCode, m.name as materialName, tu.name as unitName from t_advance_registration a left join t_advance_delivery b on a.advance_delivery_id = b.id left join t_advance_delivery_detail c on a.advance_delivery_detail_id = c.id left join t_material m on a.material_id = m.id left join t_unit tu on m.unit_id = tu.id
inner join sys_user u on u.user_name = a.create_by and u.status = '0' inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'
a.del_flag = '0' and a.advance_delivery_id = #{advanceDeliveryId}
and a.advance_delivery_detail_id = #{advanceDeliveryDetailId}
and a.material_id = #{materialId} and a.predict_count = #{predictCount} and a.actual_count = #{actualCount} and a.status = #{status} and a.batch_code like concat('%', #{batchCode}, '%')
and b.code like concat('%', #{advanceDeliveryCode}, '%')
and b.`type` = #{advanceDeliveryType}
${params.dataScope} order by a.create_time desc
